tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(135deg_in_oklab,#ff0000,#00ffff)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-135/oklab from-[#ff0000] to-[#00ffff]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(135deg in oklab, #ff0000, #00ffff);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(135deg in oklab, #ff0000, #00ffff);
}

css-variables:
:root {
  --gradient-angle: 135deg;
  --gradient-color-1: #ff0000;
  --gradient-color-2: #00ffff;
  --gradient: linear-gradient(var(--gradient-angle) in oklab, var(--gradient-color-1), var(--gradient-color-2));
}

/* Usage: background: var(--gradient); */

